from pathlib import Path
import os,json,hashlib,subprocess,re
from datetime import datetime,timezone
r=Path.cwd();l=r/'plan/04-autonomous-agent-history/phases/p06/docs/logs';producer=json.loads((l/'producer-input.json').read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
old=json.loads(Path(producer['scope']).read_text())['owned_hashes']
for n,h in old.items():assert sha(r/n)==h,n
for n,h in producer['external_paths'].items():assert (sha(r/n) if (r/n).exists() else None)==h,n
excludes=producer['exclusions'];spec=['.',*[':(top,exclude,literal)'+p for p in excludes]];paths=set()
for cmd in [['git','diff','--name-only','HEAD','--',*spec],['git','ls-files','--others','--exclude-standard','--',*spec]]:paths.update(subprocess.check_output(cmd,text=True).splitlines())
assert paths-set(producer['external_paths'])==set(old)
skill='/private/tmp/openbot-ah-p05-workflow-skill';env=os.environ.copy();env['PATH']=str(l/'tools')+os.pathsep+env['PATH'];snapshot=subprocess.check_output(['bash',skill+'/scripts/snapshot.sh',*excludes],text=True,env=env);digest=re.search(r'^digest: (\w+)$',snapshot,re.M)[1];assert digest==producer['source_digest']
(l/'AH-P06-AG1-R2-author-snapshot.txt').write_text(snapshot);scope=l/'author-scope-architecture-r2.json';save(scope,{'owned_hashes':old,'owned_count':len(old),'phase_delta':{},'status':'architecture only; unchanged acceptedP05 producer'})
a=Path('/Users/mac02/dev/openbot/plan/04-autonomous-agent-history/COORDINATION.md');pin=l/'coordination-r26.md';assert sha(a)==sha(pin)==sha(r/'plan/04-autonomous-agent-history/COORDINATION.md')
decision=l/'AH-P06-D1-r2.md';evidence=l/'AH-P06-AG1-R2.evidence.json';save(evidence,{'version':1,'round':'AH-P06-AG1-R2','artifact':digest,'checks':[{'criteria':['AC1','AC2','AC3','AC4','AC5','AC6','AC7','AC8'],'command':'planned focused P06 native/view/retention/control/level/browser and affected build checks in D1r2/TASK','fixture':'planned P06 ownedpair loopback65037; stock2MiB; existing supervised storage owner','status':'NOT EXERCISED','reason':'pre-implementation architecture gate; no P06 native/schema source edits or behavior checks yet'}]})
v=subprocess.run(['python3',skill+'/scripts/check-evidence.py',str(evidence),'--expect-artifact',digest],capture_output=True,text=True);(l/'AH-P06-AG1-R2-evidence-validation.txt').write_text(v.stdout+v.stderr);assert v.returncode==0,v.stdout+v.stderr
m={'review':'AH-P06-AG1-R2','stage':'consequential architecture only; no code acceptance','at':datetime.now(timezone.utc).isoformat(),'worktree':str(r),'branch':subprocess.check_output(['git','branch','--show-current'],text=True).strip(),'phase_start':producer['phase_start'],'review_base':producer['review_base'],'head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'source_digest':digest,'exclusions':excludes,'snapshot_adapter':str(l/'tools'),'skill':skill,'skill_sha256':sha(Path(skill)/'SKILL.md'),'decision':str(decision),'decision_revision':'AH-P06-D1/r2','decision_sha256':sha(decision),'coordination_authority':str(a),'coordination_revision':26,'coordination_sha256':sha(a),'coordination_pin':str(pin),'notices':[ *['AH-I00'+str(n)+'/r1' for n in range(1,8)],'AH-C001/r1','AH-C002/r5','AH-C003/r2','AH-C004/r3','AH-C005/r4','AH-C006/r2','AH-C007/r2 proposed'],'scope':str(scope),'scope_sha256':sha(scope),'owned_count':len(old),'owned_archive':producer['owned_archive'],'owned_archive_sha256':producer['owned_archive_sha256'],'external_paths':producer['external_paths'],'producer_source':producer['source_digest'],'producer_archive':producer['owned_archive'],'producer_archive_sha256':producer['owned_archive_sha256'],'producer_acceptance':str(l/'producer-acceptance.json'),'evidence':str(evidence),'evidence_sha256':sha(evidence),'checks_in_progress':False,'source_status':'FROZEN unchanged acceptedP05; P06 design only'}
save(l/'AH-P06-AG1-R2-input.json',m);print(json.dumps({'source':digest,'owned':len(old),'decision':m['decision_sha256'],'coord':26,'evidence':'NOT EXERCISED1; validator retentionPASS'},indent=2))
